"use strict";(globalThis.webpackChunkgrc||=[]).push([[59911],{30591(e){e.exports=JSON.parse('{"citeKey":"kougkas2020chronolog","slug":"kougkas-2020-chronolog-c458","title":"ChronoLog: A Distributed Shared Tiered Log Store with Time-based Data Ordering","authors":["A. Kougkas","H. Devarajan","K. Bateman","J. Cernuda","N. Rajesh","X.-H. Sun"],"venue":"The 36th International Conference on Massive Storage Systems and Technology (MSST\'20), Oct. 29-30, 2020","type":"Conference","entryType":"inproceedings","date":"October, 2020","year":2020,"era":"iit","month":10,"abstract":"Modern applications produce and process massive amounts of activity (or log) data. Traditional storage systems were not designed with an append-only data model and a new storage abstraction aims to fill this gap: the distributed shared log store. However, existing solutions struggle to provide a scalable, parallel, and high-performance solution that can support a diverse set of conflicting log workload requirements. Finding the tail of a distributed log is a centralized point of contention. In this paper, we show how using physical time can help alleviate the need of centralized synchronization points. We present ChronoLog, a new, distributed, shared, and multi-tiered log store that can handle more than a million tail operations per second. Evaluation results show ChronoLog\'s potential, outperforming existing solution by an order of magnitude.","hasAbstract":true,"lede":"We show how using physical time can help alleviate the need of centralized synchronization points.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-chronolog-c458.pdf"},"tags":["Distributed Log","Shared Log","Tiered Storage","ChronoLog"],"_projectIds":["chronolog"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["chronolog"],"memberAuthors":["kougkas-anthony","devarajan-hariharan","bateman-keith","cernuda-jaime","rajesh-neeraj","sun-xian-he"]}')}}]);